"use client";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-dropdown-menu";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/sahajiv-motion/use-flow";

export type DropdownMenuProps = React.ComponentProps<typeof Primitive.Root>;
export function DropdownMenu(props: DropdownMenuProps) {
  return <Primitive.Root {...props} />;
}
export type DropdownMenuPortalProps = React.ComponentProps<
  typeof Primitive.Portal
>;
export function DropdownMenuPortal(props: DropdownMenuPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type DropdownMenuGroupProps = React.ComponentProps<
  typeof Primitive.Group
>;
export function DropdownMenuGroup(props: DropdownMenuGroupProps) {
  return <Primitive.Group data-slot="dropdown-menu-group" {...props} />;
}
export type DropdownMenuRadioGroupProps = React.ComponentProps<
  typeof Primitive.RadioGroup
>;
export function DropdownMenuRadioGroup(props: DropdownMenuRadioGroupProps) {
  return (
    <Primitive.RadioGroup data-slot="dropdown-menu-radiogroup" {...props} />
  );
}
export type DropdownMenuSubProps = React.ComponentProps<typeof Primitive.Sub>;
export function DropdownMenuSub(props: DropdownMenuSubProps) {
  return <Primitive.Sub {...props} />;
}
export type DropdownMenuTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function DropdownMenuTrigger({
  className,
  ref,
  ...props
}: DropdownMenuTriggerProps) {
  return (
    <Primitive.Trigger
      ref={ref}
      data-slot="dropdown-menu-trigger"
      data-part="trigger"
      data-menu=""
      className={cn("", className)}
      {...props}
    />
  );
}
export const dropdownmenuContentVariants = cva(
  "v-menu [background:var(--popover)] [border-radius:var(--r-card-sm)] [padding:var(--s-2)] [min-width:200px] [box-shadow:var(--shadow-float)] [border:1px_solid_var(--v-border)] [display:grid] [gap:2px]",
);
export type DropdownMenuContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function DropdownMenuContent({
  className,
  ref,
  children,
  sideOffset = 6,
  ...props
}: DropdownMenuContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={flowRef}
        data-slot="dropdown-menu-content"
        data-part="content"
        sideOffset={sideOffset}
        className={cn(dropdownmenuContentVariants(), className)}
        {...props}
      >
        {children}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type DropdownMenuSubContentProps = React.ComponentProps<
  typeof Primitive.SubContent
>;
export function DropdownMenuSubContent({
  className,
  ref,
  ...props
}: DropdownMenuSubContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.SubContent
        ref={flowRef}
        data-slot="dropdown-menu-sub-content"
        data-part="content"
        className={cn(dropdownmenuContentVariants(), className)}
        {...props}
      />
    </Primitive.Portal>
  );
}
export type DropdownMenuItemProps = React.ComponentProps<
  typeof Primitive.Item
> & { variant?: "default" | "danger"; inset?: boolean };
export function DropdownMenuItem({
  className,
  variant,
  inset,
  ref,
  ...props
}: DropdownMenuItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="dropdown-menu-item"
      data-part="item"
      data-inset={inset || undefined}
      className={cn(
        "v-menu__item flex items-center gap-[var(--s-3)] min-h-10 px-[var(--s-3)] rounded-[var(--r-md)] text-[length:var(--fs-control)] w-full text-left whitespace-nowrap outline-none",
        variant === "danger" && "-danger",
        className,
      )}
      {...props}
    />
  );
}
export type DropdownMenuSubTriggerProps = React.ComponentProps<
  typeof Primitive.SubTrigger
> & { inset?: boolean };
export function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ref,
  ...props
}: DropdownMenuSubTriggerProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.SubTrigger
      ref={morphRef}
      data-slot="dropdown-menu-sub-trigger"
      data-part="item"
      data-inset={inset || undefined}
      className={cn("v-menu__item", className)}
      {...props}
    >
      {children}
      <span aria-hidden="true" className="ml-auto">
        ›
      </span>
    </Primitive.SubTrigger>
  );
}
export type DropdownMenuCheckboxItemProps = React.ComponentProps<
  typeof Primitive.CheckboxItem
>;
export function DropdownMenuCheckboxItem({
  className,
  children,
  ref,
  ...props
}: DropdownMenuCheckboxItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.CheckboxItem
      ref={morphRef}
      data-slot="dropdown-menu-checkbox-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      <Primitive.ItemIndicator
        data-slot="dropdown-menu-item-indicator"
        data-part="indicator"
      >
        ✓
      </Primitive.ItemIndicator>
      {children}
    </Primitive.CheckboxItem>
  );
}
export type DropdownMenuRadioItemProps = React.ComponentProps<
  typeof Primitive.RadioItem
>;
export function DropdownMenuRadioItem({
  className,
  children,
  ref,
  ...props
}: DropdownMenuRadioItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.RadioItem
      ref={morphRef}
      data-slot="dropdown-menu-radio-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      <Primitive.ItemIndicator
        data-slot="dropdown-menu-item-indicator"
        data-part="indicator"
      >
        ●
      </Primitive.ItemIndicator>
      {children}
    </Primitive.RadioItem>
  );
}
export type DropdownMenuLabelProps = React.ComponentProps<
  typeof Primitive.Label
>;
export function DropdownMenuLabel({
  className,
  ...props
}: DropdownMenuLabelProps) {
  return (
    <Primitive.Label
      data-slot="dropdown-menu-label"
      data-part="group"
      className={cn("v-menu__group", className)}
      {...props}
    />
  );
}
export type DropdownMenuSeparatorProps = React.ComponentProps<
  typeof Primitive.Separator
>;
export function DropdownMenuSeparator({
  className,
  ...props
}: DropdownMenuSeparatorProps) {
  return (
    <Primitive.Separator
      data-slot="dropdown-menu-separator"
      data-part="separator"
      className={cn("v-menu__sep", className)}
      {...props}
    />
  );
}
export type DropdownMenuShortcutProps = React.ComponentProps<"span">;
export function DropdownMenuShortcut({
  className,
  ...props
}: DropdownMenuShortcutProps) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        "ml-auto text-[11px] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu__item:where(
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"]
) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  ):hover,
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )[data-highlighted] {
  background: var(--v-beige);
}
.v-menu__item:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  ).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-menu__group:where(
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"]
) {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  padding: 8px 12px 4px;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-menu:where(
    [data-slot="dropdown-menu"],
    [data-slot^="dropdown-menu-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="dropdown-menu"], [data-slot^="dropdown-menu-"]) {
  scrollbar-gutter: stable;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="dropdown-menu"],
  [data-slot^="dropdown-menu-"],
  [data-slot="dropdown-menu"]::before,
  [data-slot="dropdown-menu"]::after,
  [data-slot^="dropdown-menu-"]::before,
  [data-slot^="dropdown-menu-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot^="dropdown-menu-"][data-inset] {
  padding-left: 32px;
}
[data-slot^="dropdown-menu-"][data-disabled] {
  pointer-events: none;
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot^="dropdown-menu-"][data-highlighted] {
  outline: none;
  background: var(--v-beige);
}

}
